    CHECK (
        (scope = 'session' AND session_id IS NOT NULL AND context_id IS NULL)
        OR (scope = 'context' AND context_id IS NOT NULL AND session_id IS NULL)
        OR (scope = 'global' AND session_id IS NULL AND context_id IS NULL)
    )
